import { useEffect, useState } from 'react';

const directions = ['NORTH', 'SOUTH', 'EAST', 'WEST'];

function App() {
  const [state, setState] = useState({
    emergencyMode: false,
    vehicle: { name: 'Ambulance 01', status: 'STANDBY', latitude: 12.9716, longitude: 77.5946, speedKmh: 0, heading: 'NORTH' },
    destination: { name: 'Hospital', latitude: 12.9822, longitude: 77.6194 },
    route: null,
    trafficData: null,
    signalState: { NORTH: 'RED', SOUTH: 'RED', EAST: 'RED', WEST: 'RED' },
    intersections: [],
    esp32: { connected: false, port: 'COM3', baudRate: 115200, status: 'DISCONNECTED', lastCommand: null, lastResponse: null },
    serialLog: [],
  });
  const [selectedDirection, setSelectedDirection] = useState('NORTH');

  const fetchState = async () => {
    try {
      const response = await fetch('http://localhost:5000/api/state');
      const data = await response.json();
      setState(data);
    } catch (error) {
      console.error('State fetch failed:', error);
    }
  };

  useEffect(() => {
    fetchState();
    const interval = setInterval(fetchState, 2000);
    return () => clearInterval(interval);
  }, []);

  const startEmergency = async () => {
    await fetch('http://localhost:5000/api/emergency/start', { method: 'POST', headers: { 'Content-Type': 'application/json' } });
    fetchState();
  };

  const sendManualSignal = async () => {
    await fetch('http://localhost:5000/api/signal/test', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ direction: selectedDirection }),
    });
    fetchState();
  };

  const route = state.route || {};
  const traffic = state.trafficData || {};
  const vehicle = state.vehicle || {};

  return (
    <div className="app-shell">
      <header className="topbar">
        <div>
          <p className="eyebrow">Smart Traffic Management System</p>
          <h1>Emergency Vehicle Priority</h1>
        </div>
        <button className="primary-btn" onClick={startEmergency}>Emergency Mode: {state.emergencyMode ? 'ON' : 'OFF'}</button>
      </header>

      <main className="dashboard-grid">
        <section className="card map-card">
          <div className="section-head">
            <h2>Traffic Map</h2>
            <span className={`status-pill ${state.emergencyMode ? 'on' : 'off'}`}>{state.emergencyMode ? 'EMERGENCY' : 'NORMAL'}</span>
          </div>
          <div className="map-surface">
            <div className="vehicle-dot">EV</div>
            <div className="destination-dot">DST</div>
          </div>
        </section>

        <aside className="card side-card">
          <h2>Emergency Vehicle</h2>
          <div className="info-row"><span>Vehicle</span><strong>{vehicle.name}</strong></div>
          <div className="info-row"><span>Status</span><strong>{vehicle.status}</strong></div>
          <div className="info-row"><span>Location</span><strong>{vehicle.latitude?.toFixed(4)}, {vehicle.longitude?.toFixed(4)}</strong></div>
          <div className="info-row"><span>Speed</span><strong>{vehicle.speedKmh || 0} km/h</strong></div>
          <div className="info-row"><span>ETA</span><strong>{route.etaMinutes || '--'} min</strong></div>
          <div className="info-row"><span>Destination</span><strong>{state.destination?.name}</strong></div>
        </aside>
      </main>

      <section className="metrics-grid">
        <div className="card">
          <h2>Route Details</h2>
          <div className="info-row"><span>Current Route</span><strong>{route.id || '--'}</strong></div>
          <div className="info-row"><span>Distance</span><strong>{route.distanceKm || '--'} km</strong></div>
          <div className="info-row"><span>ETA</span><strong>{route.etaMinutes || '--'} min</strong></div>
          <div className="info-row"><span>Traffic</span><strong>{route.traffic || '--'}</strong></div>
        </div>

        <div className="card">
          <h2>AI Traffic Density</h2>
          <div className="info-row"><span>Model</span><strong>{traffic.modelName || 'best.onnx'}</strong></div>
          <div className="info-row"><span>Status</span><strong>{traffic.modelStatus || 'READY'}</strong></div>
          <div className="info-row"><span>North</span><strong>{traffic.north?.trafficDensity || '--'}</strong></div>
          <div className="info-row"><span>South</span><strong>{traffic.south?.trafficDensity || '--'}</strong></div>
          <div className="info-row"><span>East</span><strong>{traffic.east?.trafficDensity || '--'}</strong></div>
          <div className="info-row"><span>West</span><strong>{traffic.west?.trafficDensity || '--'}</strong></div>
        </div>

        <div className="card">
          <h2>Signal Status</h2>
          <div className="signal-grid">
            {directions.map((direction) => (
              <div key={direction} className="signal-box">
                <span>{direction}</span>
                <strong>{state.signalState?.[direction] || 'RED'}</strong>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="bottom-grid">
        <div className="card">
          <h2>Upcoming Intersections</h2>
          {(state.intersections || []).map((intersection) => (
            <div key={intersection.id} className="intersection-item">
              <strong>{intersection.id}</strong>
              <span>{intersection.direction}</span>
              <em>{intersection.status}</em>
            </div>
          ))}
        </div>

        <div className="card">
          <h2>ESP32 Status</h2>
          <div className="info-row"><span>Connection</span><strong>{state.esp32?.connected ? 'CONNECTED' : 'DISCONNECTED'}</strong></div>
          <div className="info-row"><span>Port</span><strong>{state.esp32?.port || 'COM3'}</strong></div>
          <div className="info-row"><span>Baud Rate</span><strong>{state.esp32?.baudRate || 115200}</strong></div>
          <div className="info-row"><span>Last Command</span><strong>{state.esp32?.lastCommand || 'NONE'}</strong></div>
          <div className="info-row"><span>Last Response</span><strong>{state.esp32?.lastResponse || 'NONE'}</strong></div>
        </div>

        <div className="card">
          <h2>Manual Test Signal</h2>
          <label className="select-wrap">
            <span>Direction</span>
            <select value={selectedDirection} onChange={(e) => setSelectedDirection(e.target.value)}>
              {directions.map((dir) => (
                <option key={dir} value={dir}>{dir}</option>
              ))}
            </select>
          </label>
          <button className="primary-btn full" onClick={sendManualSignal}>Send Test Signal</button>
        </div>
      </section>

      <section className="card serial-panel">
        <h2>Serial Monitor</h2>
        <div className="serial-log">
          {(state.serialLog || []).map((entry, index) => (
            <div key={`${entry.timestamp}-${index}`} className="log-line">
              <span>{entry.direction}</span>
              <strong>{entry.payload}</strong>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

export default App;
